/// Parse a timeout such as `30s`, `1.5s`, or `500ms` into milliseconds.
pub fn parse_timeout(raw: &str) -> u64 {
    let value = raw.trim();
    let (digits, scale) = match value.strip_suffix("ms") {
        Some(ms) => (ms, 1),
        None => match value.strip_suffix('s') {
            Some(s) => (s, 1000),
            None => (value, 1),
        },
    };
    let digits = digits.trim();
    if let Ok(n) = digits.parse::<u64>() {
        return n.saturating_mul(scale);
    }
    // Fractional values are only meaningful with the seconds suffix; the cast
    // saturates at u64::MAX, preserving totality for oversized inputs.
    if scale == 1000 {
        if let Ok(secs) = digits.parse::<f64>() {
            if secs.is_finite() && secs >= 0.0 {
                return (secs * 1000.0) as u64;
            }
        }
    }
    DEFAULT_TIMEOUT_MS
}

